function toBinary(n) {
  if (n === 0) return "0";
  let binary = "";
  let num = Math.abs(n);
  while (num > 0) {
    binary = (num % 2) + binary;
    num = Math.floor(num / 2);
  }
  return n < 0 ? "-" + binary : binary;
}
